// Simple DI Container — no external dependencies
public class DIContainer
{
    private readonly Dictionary<Type, object> singletons = new();
    private readonly Dictionary<Type, Func<object>> factories = new();

    public void RegisterSingleton<T>(T instance) where T : class
    {
        singletons[typeof(T)] = instance;
    }

    public void RegisterFactory<T>(Func<T> factory) where T : class
    {
        factories[typeof(T)] = () => factory();
    }

    public T Resolve<T>() where T : class
    {
        Type type = typeof(T);

        if (singletons.TryGetValue(type, out object singleton))
            return singleton as T;

        if (factories.TryGetValue(type, out Func<object> factory))
            return factory() as T;

        throw new InvalidOperationException($"No registration for {type.Name}");
    }
}

// Bootstrapper — wires everything at game start
public class GameBootstrapper : MonoBehaviour
{
    [SerializeField] private AudioManager audioManager;
    [SerializeField] private GameStateManager gameState;
    [SerializeField] private UIManager uiManager;

    public static DIContainer Container { get; private set; }

    void Awake()
    {
        Container = new DIContainer();

        // Register singletons
        Container.RegisterSingleton<IAudioService>(audioManager);
        Container.RegisterSingleton<IGameStateService>(gameState);
        Container.RegisterSingleton<IUIService>(uiManager);

        // Register factories for transient objects
        Container.RegisterFactory<DamageCalculator>(() => new DamageCalculator(
            Container.Resolve<IArmorSystem>(),
            Container.Resolve<ICriticalHitSystem>()
        ));

        DontDestroyOnLoad(gameObject);
    }
}

