// ============================================
// GENERIC STATE MACHINE
// ============================================
public class StateMachine<T> where T : Enum
{
    public T CurrentState { get; private set; }
    public T PreviousState { get; private set; }

    private readonly Dictionary<T, State<T>> states = new();
    private State<T> currentStateInstance;

    public void AddState(T stateKey, State<T> state)
    {
        states[stateKey] = state;
        state.StateMachine = this;
    }

    public void ChangeState(T newState)
    {
        if (!states.TryGetValue(newState, out State<T> nextState))
        {
            Debug.LogError($"State {newState} not registered!");
            return;
        }

        // Exit current state
        currentStateInstance?.OnExit();

        // Transition
        PreviousState = CurrentState;
        CurrentState = newState;
        currentStateInstance = nextState;

        // Enter new state
        currentStateInstance.OnEnter();
    }

    public void Update() => currentStateInstance?.OnUpdate();
    public void FixedUpdate() => currentStateInstance?.OnFixedUpdate();
}

public abstract class State<T> where T : Enum
{
    public StateMachine<T> StateMachine { get; set; }
    public abstract void OnEnter();
    public abstract void OnUpdate();
    public abstract void OnFixedUpdate();
    public abstract void OnExit();
}

using UnityEngine;

public enum EnemyState { Idle, Patrol, Chase, Attack, Stunned, Dead }

public class EnemyAI : MonoBehaviour
{
    private StateMachine<EnemyState> stateMachine;

    [SerializeField] private float detectionRange = 15f;
    [SerializeField] private float attackRange = 2f;
    [SerializeField] private float patrolSpeed = 2f;
    [SerializeField] private float chaseSpeed = 5f;

    private Transform player;
    private float stunTimer;
    private float attackCooldown;
    private int health = 100;
    private Rigidbody rb;
    private Animator animator;

    void Awake()
    {
        player = GameObject.FindWithTag("Player").transform;

        stateMachine = new StateMachine<EnemyState>();

        stateMachine.AddState(EnemyState.Idle, new IdleState(this));
        stateMachine.AddState(EnemyState.Patrol, new PatrolState(this));
        stateMachine.AddState(EnemyState.Chase, new ChaseState(this));
        stateMachine.AddState(EnemyState.Attack, new AttackState(this));
        stateMachine.AddState(EnemyState.Stunned, new StunnedState(this));
        stateMachine.AddState(EnemyState.Dead, new DeadState(this));

        stateMachine.ChangeState(EnemyState.Idle);
    }

    void Start()
    {
        rb = GetComponent<Rigidbody>();
        animator = GetComponent<Animator>();
    }

    void Update()
    {
        stateMachine.Update();

        // Global transition: death overrides any state
        if (health <= 0 && stateMachine.CurrentState != EnemyState.Dead)
        {
            stateMachine.ChangeState(EnemyState.Dead);
        }
    }

    void FixedUpdate() => stateMachine.FixedUpdate();

    public void TakeDamage(int damage, float stunDuration = 0f)
    {
        health -= damage;
        if (stunDuration > 0 && health > 0)
        {
            stunTimer = stunDuration;
            stateMachine.ChangeState(EnemyState.Stunned);
        }
    }

    // ============================================
    // STATE IMPLEMENTATIONS
    // ============================================
    private class IdleState : State<EnemyState>
    {
        private EnemyAI ai;
        private float waitTimer;
        public IdleState(EnemyAI ai) => this.ai = ai;

        public override void OnEnter() => waitTimer = Random.Range(1f, 3f);

        public override void OnUpdate()
        {
            waitTimer -= Time.deltaTime;
            float dist = Vector3.Distance(ai.transform.position, ai.player.position);

            if (dist < ai.detectionRange)
            {
                StateMachine.ChangeState(EnemyState.Chase);
                return;
            }
            if (waitTimer <= 0)
                StateMachine.ChangeState(EnemyState.Patrol);
        }

        public override void OnFixedUpdate() { }
        public override void OnExit() { }
    }

    private class ChaseState : State<EnemyState>
    {
        private EnemyAI ai;
        public ChaseState(EnemyAI ai) => this.ai = ai;

        public override void OnEnter() { }

        public override void OnUpdate()
        {
            float dist = Vector3.Distance(ai.transform.position, ai.player.position);
            if (dist < ai.attackRange)
            {
                StateMachine.ChangeState(EnemyState.Attack);
                return;
            }
            if (dist > ai.detectionRange * 1.5f)
                StateMachine.ChangeState(EnemyState.Idle);
        }

        public override void OnFixedUpdate()
        {
            Vector3 dir = (ai.player.position - ai.transform.position).normalized;
            ai.rb.velocity = dir * ai.chaseSpeed;
        }

        public override void OnExit() => ai.rb.velocity = Vector3.zero;
    }

    private class AttackState : State<EnemyState>
    {
        private EnemyAI ai;
        private float attackTimer;
        public AttackState(EnemyAI ai) => this.ai = ai;

        public override void OnEnter() => attackTimer = 0f;

        public override void OnUpdate()
        {
            attackTimer -= Time.deltaTime;
            float dist = Vector3.Distance(ai.transform.position, ai.player.position);

            if (dist > ai.attackRange * 1.2f)
            {
                StateMachine.ChangeState(EnemyState.Chase);
                return;
            }
            if (attackTimer <= 0)
            {
                ai.animator.SetTrigger("Attack");
                attackTimer = ai.attackCooldown;
            }
        }

        public override void OnFixedUpdate() { }
        public override void OnExit() { }
    }

    private class StunnedState : State<EnemyState>
    {
        private EnemyAI ai;
        public StunnedState(EnemyAI ai) => this.ai = ai;

        public override void OnEnter()
        {
            ai.animator.SetBool("Stunned", true);
            ai.rb.velocity = Vector3.zero;
        }

        public override void OnUpdate()
        {
            ai.stunTimer -= Time.deltaTime;
            if (ai.stunTimer <= 0)
                StateMachine.ChangeState(EnemyState.Chase);
        }

        public override void OnFixedUpdate() { }
        public override void OnExit() => ai.animator.SetBool("Stunned", false);
    }

    private class DeadState : State<EnemyState>
    {
        private EnemyAI ai;
        public DeadState(EnemyAI ai) => this.ai = ai;

        public override void OnEnter()
        {
            ai.animator.SetTrigger("Die");
            ai.rb.isKinematic = true;
            ai.GetComponent<Collider>().enabled = false;

            EventBus<EnemyDiedEvent>.Publish(new EnemyDiedEvent
            {
                Enemy = ai,
                Position = ai.transform.position,
                ScoreValue = 100
            });
        }

        public override void OnUpdate() { }
        public override void OnFixedUpdate() { }
        public override void OnExit() { }
    }
}

