public class ObjectDistributorWindow : EditorWindow
{
    private GameObject prefabToDistribute;
    private int count = 10;
    private float radius = 20f;
    private float minDistance = 2f;
    private bool randomRotation = true;
    private bool randomScale = false;
    private Vector2 scaleRange = new Vector2(0.8f, 1.2f);
    private LayerMask groundLayer;
    private Vector3 center;
    private bool useSelectionCenter = true;

    [MenuItem("Tools/Level Design/Object Distributor")]
    public static void ShowWindow()
    {
        GetWindow<ObjectDistributorWindow>("Object Distributor");
    }

    void OnGUI()
    {
        GUILayout.Label("Object Distributor", EditorStyles.boldLabel);
        EditorGUILayout.Space(5);
        prefabToDistribute = (GameObject)EditorGUILayout.ObjectField("Prefab", prefabToDistribute, typeof(GameObject), false);
        count = EditorGUILayout.IntSlider("Count", count, 1, 500);
        radius = EditorGUILayout.Slider("Radius", radius, 1f, 200f);
        minDistance = EditorGUILayout.Slider("Min Distance", minDistance, 0.1f, 10f);
        randomRotation = EditorGUILayout.Toggle("Random Rotation", randomRotation);
        randomScale = EditorGUILayout.Toggle("Random Scale", randomScale);
        if (randomScale) EditorGUILayout.MinMaxSlider(ref scaleRange.x, ref scaleRange.y, 0.1f, 3f);
        groundLayer = EditorGUILayout.LayerField("Ground Layer", groundLayer);
        useSelectionCenter = EditorGUILayout.Toggle("Use Selection Center", useSelectionCenter);
        if (!useSelectionCenter) center = EditorGUILayout.Vector3Field("Center", center);
        EditorGUILayout.Space(10);
        GUI.backgroundColor = new Color(0.4f, 0.8f, 0.4f);
        if (GUILayout.Button("Distribute Objects", GUILayout.Height(40))) DistributeObjects();
        GUI.backgroundColor = Color.white;
        EditorGUILayout.Space(5);
        GUI.backgroundColor = new Color(0.9f, 0.3f, 0.3f);
        if (GUILayout.Button("Clear Last Distribution", GUILayout.Height(30))) Undo.PerformUndo();
        GUI.backgroundColor = Color.white;
    }

    void DistributeObjects()
    {
        if (prefabToDistribute == null)
        {
            EditorUtility.DisplayDialog("Error", "Please assign a prefab!", "OK");
            return;
        }
        if (useSelectionCenter && Selection.activeGameObject != null)
            center = Selection.activeGameObject.transform.position;
        List<Vector3> placedPositions = new List<Vector3>();
        int attempts = 0;
        int placed = 0;
        Undo.SetCurrentGroupName("Distribute Objects");
        int group = Undo.GetCurrentGroup();
        while (placed < count && attempts < count * 50)
        {
            attempts++;
            Vector2 randomCircle = UnityEngine.Random.insideUnitCircle * radius;
            Vector3 candidate = center + new Vector3(randomCircle.x, 100f, randomCircle.y);
            if (Physics.Raycast(candidate, Vector3.down, out RaycastHit hit, 200f, groundLayer))
            {
                candidate.y = hit.point.y;
                bool tooClose = placedPositions.Any(p => Vector3.Distance(p, candidate) < minDistance);
                if (tooClose) continue;
                GameObject instance = PrefabUtility.InstantiatePrefab(prefabToDistribute) as GameObject;
                instance.transform.position = candidate;
                if (randomRotation) instance.transform.rotation = Quaternion.Euler(0, UnityEngine.Random.Range(0f, 360f), 0);
                if (randomScale)
                {
                    float s = UnityEngine.Random.Range(scaleRange.x, scaleRange.y);
                    instance.transform.localScale = Vector3.one * s;
                }
                Undo.RegisterCreatedObjectUndo(instance, "Distribute Object");
                placedPositions.Add(candidate);
                placed++;
            }
        }
        Undo.CollapseUndoOperations(group);
        EditorUtility.DisplayDialog("Done", $"Placed {placed} objects.", "OK");
    }
}

