// Allocator types:
// Persistent — lives until manually disposed (use for long-lived data)
// Temp — fastest, lasts one frame, auto-disposed (use for short-lived jobs)
// TempJob — lasts 4 frames, auto-disposed (use for jobs that span multiple frames)

NativeArray<int> persistent = new NativeArray<int>(100, Allocator.Persistent);
NativeArray<int> temp = new NativeArray<int>(100, Allocator.Temp);
NativeArray<int> tempJob = new NativeArray<int>(100, Allocator.TempJob);

// ALWAYS dispose Persistent arrays!
persistent.Dispose();

// Temp is auto-disposed but you can dispose early
temp.Dispose();

// TempJob auto-disposes after 4 frames
tempJob.Dispose();

// Safety: NativeArray has IsCreated property
if (persistent.IsCreated)
    persistent.Dispose();

using UnityEngine;
using Unity.Collections;
using Unity.Jobs;
using Unity.Mathematics;

public struct DistanceJob : IJobParallelFor
{
    [ReadOnly] public NativeArray<float3> positions;
    [ReadOnly] public float3 target;
    public NativeArray<float> distances;

    public void Execute(int index)
    {
        float3 diff = positions[index] - target;
        distances[index] = math.lengthsq(diff);
    }
}

public struct FindNearestJob : IJob
{
    [ReadOnly] public NativeArray<float> distances;
    [ReadOnly] public NativeArray<float3> positions;
    public NativeArray<int> nearestIndex;
    public NativeArray<float> minDistance;

    public void Execute()
    {
        float min = float.MaxValue;
        int nearest = -1;
        for (int i = 0; i < distances.Length; i++)
        {
            if (distances[i] < min)
            {
                min = distances[i];
                nearest = i;
            }
        }
        nearestIndex[0] = nearest;
        minDistance[0] = math.sqrt(min);
    }
}

public class JobChainDemo : MonoBehaviour
{
    [SerializeField] private Transform target;
    [SerializeField] private int objectCount = 5000;

    private NativeArray<float3> positions;
    private NativeArray<float> distances;
    private NativeArray<int> nearestIndex;
    private NativeArray<float> minDistance;
    private Transform[] transforms;

    void Start()
    {
        positions = new NativeArray<float3>(objectCount, Allocator.Persistent);
        distances = new NativeArray<float>(objectCount, Allocator.Persistent);
        nearestIndex = new NativeArray<int>(1, Allocator.Persistent);
        minDistance = new NativeArray<float>(1, Allocator.Persistent);
        transforms = new Transform[objectCount];

        for (int i = 0; i < objectCount; i++)
        {
            var obj = GameObject.CreatePrimitive(PrimitiveType.Cube);
            Destroy(obj.GetComponent<Collider>());
            obj.transform.position = UnityEngine.Random.insideUnitSphere * 30f;
            transforms[i] = obj.transform;
            positions[i] = obj.transform.position;
        }
    }

    void Update()
    {
        float3 targetPos = target.position;
        DistanceJob distanceJob = new DistanceJob
        {
            positions = positions,
            target = targetPos,
            distances = distances
        };
        JobHandle distanceHandle = distanceJob.ScheduleParallel(objectCount, 64, default);

        FindNearestJob findJob = new FindNearestJob
        {
            distances = distances,
            positions = positions,
            nearestIndex = nearestIndex,
            minDistance = minDistance
        };
        JobHandle findHandle = findJob.Schedule(distanceHandle);
        findHandle.Complete();

        int nearest = nearestIndex[0];
        if (nearest >= 0)
        {
            transforms[nearest].GetComponent<Renderer>().material.color = Color.red;
            for (int i = 0; i < objectCount; i++)
                if (i != nearest)
                    transforms[i].GetComponent<Renderer>().material.color = Color.white;
        }
    }

    void OnDestroy()
    {
        positions.Dispose();
        distances.Dispose();
        nearestIndex.Dispose();
        minDistance.Dispose();
    }
}

using Unity.Collections;
using Unity.Jobs;
using Unity.Mathematics;

public struct SortJob : IJob
{
    public NativeArray<float> values;
    public NativeArray<int> indices;

    public void Execute()
    {
        // Simple bubble sort for demonstration
        for (int i = 0; i < values.Length - 1; i++)
        {
            for (int j = 0; j < values.Length - i - 1; j++)
            {
                if (values[j] > values[j + 1])
                {
                    (values[j], values[j + 1]) = (values[j + 1], values[j]);
                    (indices[j], indices[j + 1]) = (indices[j + 1], indices[j]);
                }
            }
        }
    }
}

public struct ProcessTopNJob : IJobParallelFor
{
    [ReadOnly] public NativeArray<float> sortedValues;
    [ReadOnly] public NativeArray<int> sortedIndices;
    [WriteOnly] public NativeArray<float3> outputPositions;
    public int topN;

    public void Execute(int index)
    {
        if (index < topN)
        {
            // Process top N closest objects
            outputPositions[index] = new float3(sortedValues[index], sortedIndices[index], 0);
        }
    }
}

