        foreach (var (transform, movement) in 
            SystemAPI.Query<RefRW<LocalTransform>, RefRO<MovementData>>())
        {
            float3 displacement = movement.ValueRO.velocity * movement.ValueRO.speed * deltaTime;
            transform.ValueRW.Position += displacement;
        }
    }

    public void OnDestroy(ref SystemState state) { }
}

