using UnityEngine;
using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;
using Unity.Mathematics;

[BurstCompile(CompileSynchronously = true)]
public struct SpatialHashJob : IJobParallelFor
{
    [ReadOnly] public NativeArray<float3> positions;
    [ReadOnly] public float cellSize;
    [WriteOnly] public NativeArray<int> cellHashes;

    public void Execute(int index)
    {
        float3 pos = positions[index];
        int3 cell = (int3)math.floor(pos / cellSize);
        const int p1 = 73856093;
        const int p2 = 19349663;
        const int p3 = 83492791;
        cellHashes[index] = (cell.x * p1) ^ (cell.y * p2) ^ (cell.z * p3);
    }
}

public class BurstComparison : MonoBehaviour
{
    [SerializeField] private int count = 100000;

    private NativeArray<float3> positions;
    private NativeArray<float3> resultsBurst;
    private Vector3[] managedArray;

    void Start()
    {
        positions = new NativeArray<float3>(count, Allocator.Persistent);
        resultsBurst = new NativeArray<float3>(count, Allocator.Persistent);
        managedArray = new Vector3[count];

        for (int i = 0; i < count; i++)
            positions[i] = UnityEngine.Random.insideUnitSphere * 100f;
    }

    void Update()
    {
        var burstJob = new NormalizeJob
        {
            input = positions,
            output = resultsBurst
        };
        var handle = burstJob.ScheduleParallel(count, 64, default);
        handle.Complete();

        for (int i = 0; i < count; i++)
            managedArray[i] = positions[i].normalized;
    }

    [BurstCompile]
    struct NormalizeJob : IJobParallelFor
    {
        [ReadOnly] public NativeArray<float3> input;
        [WriteOnly] public NativeArray<float3> output;

        public void Execute(int index)
        {
            output[index] = math.normalize(input[index]);
        }
    }

    void OnDestroy()
    {
        positions.Dispose();
        resultsBurst.Dispose();
    }
}

// Key Unity.Mathematics replacements:
// Vector3  -> float3 (SIMD-friendly struct)
// Vector2  -> float2
// Quaternion -> quaternion
// Mathf    -> math (static class with Burst-optimized methods)

// Performance tips:
// math.lengthsq() is faster than math.length() when comparing distances
// math.dot(), math.cross(), math.normalize() all auto-vectorize with Burst
// math.select() is a branchless conditional — faster than if/else in tight loops
// math.clamp(), math.lerp(), math.saturate() are all SIMD-accelerated

[BurstCompile]
struct PhysicsJob : IJobParallelFor
{
    [ReadOnly] public NativeArray<float3> positions;
    [ReadOnly] public NativeArray<float3> velocities;
    [ReadOnly] public float deltaTime;
    [ReadOnly] public float3 gravity;
    public NativeArray<float3> newPositions;
    public NativeArray<float3> newVelocities;

    public void Execute(int index)
    {
        float3 pos = positions[index];
        float3 vel = velocities[index];

        vel += gravity * deltaTime;
        pos += vel * deltaTime;

        // Ground collision — branchless
        bool onGround = pos.y < 0f;
        pos.y = math.select(pos.y, 0f, onGround);
        vel.y = math.select(vel.y, 0f, onGround);

        newPositions[index] = pos;
        newVelocities[index] = vel;
    }
}
